update public.exercises set illustration_url='/exercises/standing-calf-raise.svg',source='Original Let’s Bulk schematic',source_license='CC0-1.0',illustration_author='Let’s Bulk project',illustration_style='two-position schematic',instructions='["Stand tall with feet hip-width apart. Use a wall for light balance support if needed.", "Keep your knees softly straight and lift your heels, rising onto the balls of your feet.", "Pause briefly, then lower slowly. Keep your ankles upright rather than rolling them out."]'::jsonb,common_mistakes='["Bouncing instead of controlling the descent.", "Rolling your ankles outward or bending your knees to lift."]'::jsonb where slug='standing-calf-raise';
update public.exercises set illustration_url='/exercises/goblet-squat-0.jpg',source='https://github.com/yuhonas/free-exercise-db',source_license='Unlicense',illustration_author='Free Exercise DB contributors',illustration_style='reference illustration (kettlebell shown)',instructions='["Hold one dumbbell vertically by its upper end close to your chest. The reference image shows the equivalent kettlebell grip.", "Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight.", "At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions."]'::jsonb,common_mistakes='["Rushing or swinging through the movement.", "Using a range or load you cannot control. Stop if the movement hurts."]'::jsonb where slug='goblet-squat';
